                    i += 2;
                    continue;
                }
                i++;
                break;
            }
            if (t[i] == '\n')
                csv->line++;
            qs_strbuf_putc(sb, t[i]);
            i++;
        }
    }
    while (!at_line_end(csv, i) && t[i] != csv->delim) {
        qs_strbuf_putc(sb, t[i]);
        i++;
